"use client";

import { useState, useRef, useEffect } from "react";
import Message from "./Message";
import Header from "./Header";
import { Smile, Send, Paperclip, X } from "lucide-react";
import { Picker, EmojiType } from "ms-3d-emoji-picker";
import { PlaceholdersAndVanishInput } from "@/components/ui/placeholders-and-vanish-input";
import { motion, AnimatePresence } from "framer-motion";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import isToday from "dayjs/plugin/isToday";
import isYesterday from "dayjs/plugin/isYesterday";
import SearchModal from "./SearchModal";
import { useSidebar } from "../Context/context";

dayjs.extend(relativeTime);
dayjs.extend(isToday);
dayjs.extend(isYesterday);

interface MessageType {
  id: number;
  text: string;
  sender: "sender" | "receiver";
  time: string;
  conversationId: string;
  date: string;
  file?: {
    name: string;
    type: string;
    url: string;
  } | null;
}

interface Conversation {
  id: string;
  name: string;
  avatar: string;
}

interface ChatWindowProps {
  conversation: Conversation;
  messages: MessageType[];
  sharedMedia: string[];
  sharedLinks: string[];
  sharedDocs: { name: string; url: string }[];
}

const ChatWindow: React.FC<ChatWindowProps> = ({
  conversation,
  messages: initialMessages,
  sharedMedia,
  sharedLinks,
  sharedDocs,
}) => {
  const [messages, setMessages] = useState<MessageType[]>(initialMessages);
  const [newestMessageId, setNewestMessageId] = useState<number | null>(null);

  const [message, setMessage] = useState<string>("");
  const [showPicker, setShowPicker] = useState<boolean>(false);
  const [sidebarOpen, setSidebarOpen] = useState<boolean>(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const pickerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        pickerRef.current &&
        !pickerRef.current.contains(event.target as Node)
      ) {
        setShowPicker(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);
  const { setIsmodel, setSelectedImage } = useSidebar();
  const [activeTab, setActiveTab] = useState("media");

  const openImageModal = (imgUrl: string) => {
    setSelectedImage(imgUrl);
    setIsmodel(true);
  };
  const handleSend = (
    textMessage: any,
    file: MessageType["file"] = null
  ): void => {
    if (textMessage?.trim() || file) {
      const newMessage: MessageType = {
        id: messages.length + 1,
        text: textMessage,
        sender: "sender",
        time: dayjs().format("h:mm A"),
        date: dayjs().format("YYYY-MM-DD"),
        conversationId: conversation.id,
        file,
      };
      setNewestMessageId(newMessage.id);
      setMessages([...messages, newMessage]);
      
    } else {
      textMessage == null ? null : message;
      
    }
    setMessage("");

   
  };
  const handleEmojiSelect = (selectedEmoji: EmojiType) => {
    const emojiMessage = `<img src="${selectedEmoji.url}" alt="emoji" class="w-full h-full inline-block" />`;
    handleSend(emojiMessage);
    setShowPicker(false);
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const fileUrl = URL.createObjectURL(file);
      const fileMessage = {
        name: file.name,
        type: file.type,
        url: fileUrl,
      };

      handleSend("", fileMessage);
    }
  };

  const groupedMessages: Record<string, MessageType[]> = messages
    .filter((msg) => msg.conversationId === conversation.id)
    .reduce((acc, msg) => {
      if (!acc[msg.date]) acc[msg.date] = [];
      acc[msg.date].push(msg);
      return acc;
    }, {} as Record<string, MessageType[]>);

  const [search, setSearch] = useState(false);
  const handleSearch = () => {
    setSearch(true);
    console.log("serach");
  };
  const fileInputRefs = useRef<HTMLInputElement>(null);
  const wallpaperInputRef = useRef<HTMLInputElement>(null);
  const [wallpaper, setWallpaper] = useState<string>("");
  const [showWallpaperModal, setShowWallpaperModal] = useState(false);
  const [customColor, setCustomColor] = useState<string>("#000000");

  const handleWallpaperUpload = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const file = event.target.files?.[0];
    if (file) {
      const fileUrl = URL.createObjectURL(file);
      setWallpaper(`url(${fileUrl})`);
      setShowWallpaperModal(false);
    }
  };
  const handleColorChange = (color: string) => {
    setWallpaper(color);
    setShowWallpaperModal(false);
  };

  return (
    <div className="flex h-screen  ">
      <div
        className={`flex flex-col flex-1 ${
          sidebarOpen ? "lg:w-2/3" : "w-full"
        }`}
      >
        {search ? (
          <SearchModal setSearch={setSearch} />
        ) : (
          <Header
            conversation={conversation}
            search={search}
            setSearch={setSearch}
            handleSearch={handleSearch}
            onAvatarClick={() => setSidebarOpen(true)}
          />
        )}

        <div
          className="flex-1 overflow-y-auto p-4"
          style={{
            background: wallpaper || "black",
            backgroundSize: "cover",
            backgroundPosition: "center",
          }}
        >
          {Object.entries(groupedMessages).map(([date, msgs]) => (
            <div key={date}>
              <div className="text-center bg-slate-300/10 w-fit mx-auto py-2 px-4 rounded-full text-xs text-gray-400   my-4">
                {dayjs(date).isToday()
                  ? "Today"
                  : dayjs(date).isYesterday()
                  ? "Yesterday"
                  : dayjs(date).format("DD MMM, YYYY")}
              </div>
              <AnimatePresence>
                {msgs.map((msg) => (
                  <Message
                    key={msg.id}
                    message={msg}
                    isOwnMessage={msg.sender === "sender"}
                    isNewestMessage={msg.id === newestMessageId}
                    setNewestMessageId={setNewestMessageId}
                  />
                ))}
              </AnimatePresence>
            </div>
          ))}
        <div ref={messagesEndRef} />
        </div>
        <div className="sticky bottom-0 border-t border-gray-700 bg-zinc-900 p-4">
          <div className="flex items-center gap-3 p-4 bg-zinc-800 rounded-lg relative">
            <div ref={pickerRef} className="relative">
              <button
                onClick={() => setShowPicker(!showPicker)}
                className="p-2 rounded-lg hover:bg-zinc-700 transition"
              >
                <Smile className="w-6 h-6 text-gray-400 hover:text-white" />
              </button>
              {showPicker && (
                <div className="absolute bottom-12 left-0 bg-transparent shadow-lg rounded-lg z-50">
                  <Picker isOpen={true} handleEmojiSelect={handleEmojiSelect} />
                </div>
              )}
            </div>
            <button
              onClick={() => fileInputRef.current?.click()}
              className="p-2 rounded-lg hover:bg-zinc-700 transition"
            >
              <Paperclip className="w-6 h-6 text-gray-400 hover:text-white" />
            </button>
            <input
              type="file"
              ref={fileInputRef}
              className="hidden"
              onChange={handleFileUpload}
              accept=".pdf,.doc,.docx,.txt,.jpg,.png"
            />

            <div className="flex-1">
              <PlaceholdersAndVanishInput
                placeholders={["Type a message..."]}
                onChange={(e: any) => setMessage(e.target.value)}
                onSubmit={() => handleSend(message)}
              />
            </div>
            {/* <button
              onClick={() => handleSend(message)}
              className="p-2 rounded-lg hover:bg-zinc-700 transition"
            >
              <Send className="w-6 h-6 text-blue-500 hover:text-blue-400" />
            </button> */}
          </div>
        </div>
      </div>
      {sidebarOpen && (
        <div className="w-1/3 bg-zinc-800 p-6 shadow-lg border-l border-gray-700 relative">
          <button
            onClick={() => setSidebarOpen(false)}
            className="absolute top-4 right-4"
          >
            <X className="w-6 h-6 text-gray-400" />
          </button>

          <div className="text-center">
            <img
              src={conversation.avatar}
              alt={conversation.name}
              className="w-24 h-24 rounded-full mx-auto shadow-md"
            />
            <h2 className="text-white text-lg font-semibold mt-4">
              {conversation.name}
            </h2>
          </div>
          <div className="mt-4 text-gray-300 text-sm">
            <h3 className="font-semibold">🔔 Notifications</h3>
            <p>Turn on/off message notifications for this chat.</p>
            <button className="bg-blue-500 px-4 py-2 mt-2 rounded-md text-white">
              Toggle Notifications
            </button>

            <h3 className="mt-4 font-semibold">⏳ Disappearing Messages</h3>
            <p>Enable disappearing messages for privacy.</p>
            <button className="bg-red-500 px-4 py-2 mt-2 rounded-md text-white">
              Enable Disappearing
            </button>
          </div>
          <div className="mt-6">
            <div className="flex justify-around border-b border-gray-600 pb-2">
              {["media", "links", "docs"].map((tab) => (
                <button
                  key={tab}
                  onClick={() => setActiveTab(tab)}
                  className={`text-gray-400 px-4 py-2 ${
                    activeTab === tab
                      ? "text-white border-b-2 border-blue-400"
                      : ""
                  }`}
                >
                  {tab.charAt(0).toUpperCase() + tab.slice(1)}
                </button>
              ))}
            </div>
            {activeTab === "media" && (
              <div className="grid grid-cols-3 gap-2 mt-4">
                {sharedMedia.map((img, index) => (
                  <img
                    key={index}
                    src={img}
                    className="h-full w-full rounded-lg cursor-pointer object-cover shadow-sm"
                    onClick={() => openImageModal(img)}
                  />
                ))}
              </div>
            )}
            {activeTab === "links" && (
              <div className="mt-4 space-y-2">
                {sharedLinks.map((link, index) => (
                  <a
                    key={index}
                    href={link}
                    target="_blank"
                    rel="noopener noreferrer"
                    className=" bg-zinc-700 p-3 rounded-lg flex items-center gap-3 hover:bg-zinc-600 transition"
                  >
                    🔗
                    <span className="text-blue-400 truncate">{link}</span>
                  </a>
                ))}
              </div>
            )}

            {activeTab === "docs" && (
              <div className="mt-4 space-y-3">
                {sharedDocs.map((doc, index) => (
                  <div
                    key={index}
                    className="flex justify-between items-center bg-zinc-700 p-3 rounded-lg hover:bg-zinc-600 transition"
                  >
                    <div className="flex items-center gap-3 text-gray-300">
                      📄 <span>{doc.name}</span>
                    </div>
                    <a
                      href={doc.url}
                      className="bg-blue-500 text-white px-3 py-1 rounded-md text-sm hover:bg-blue-600 transition"
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      Download
                    </a>
                  </div>
                ))}
              </div>
            )}
          </div>
          <div className=" py-5  relative">
            <button
              onClick={() => setShowWallpaperModal(true)}
              className="bg-blue-500 px-4 py-2 mt-2 rounded-md text-white"
            >
              Change Wallpaper
            </button>
          </div>
          {showWallpaperModal && (
            <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center">
              <div className="bg-zinc-800 p-6 rounded-lg shadow-lg w-80 text-white relative">
                <button
                  onClick={() => setShowWallpaperModal(false)}
                  className="absolute top-4 right-4"
                >
                  <X className="w-6 h-6 text-gray-400" />
                </button>

                <h2 className="text-lg font-semibold mb-4">Change Wallpaper</h2>
                <h3 className="text-sm text-gray-400 mb-2">Choose a Color</h3>
                <div className="flex gap-3 flex-wrap mb-4">
                  {[
                    "#1E1E1E",
                    "#091E427D",
                    "#2C3E5D",
                    "#B3B9C4",
                    "#2C333A",
                    "#C3DEFE33",
                  ].map((color) => (
                    <button
                      key={color}
                      className="w-10 h-10 rounded-full border-2 border-gray-400"
                      style={{ backgroundColor: color }}
                      onClick={() => handleColorChange(color)}
                    />
                  ))}
                </div>

                <h3 className="text-sm text-gray-400 mb-2">
                  Pick a Custom Color
                </h3>
                <input
                  type="color"
                  value={customColor}
                  onChange={(e) => {
                    setCustomColor(e.target.value);
                    handleColorChange(e.target.value);
                  }}
                  className="w-full h-10 border-none bg-transparent cursor-pointer"
                />
                <button
                  onClick={() => wallpaperInputRef.current?.click()}
                  className="bg-blue-500 w-full mx-auto px-4 py-2 rounded-md mt-3 text-white flex items-center justify-center gap-2"
                >
                  📷 Upload Image
                </button>
                <input
                  type="file"
                  ref={wallpaperInputRef}
                  className="hidden"
                  accept="image/*"
                  onChange={handleWallpaperUpload}
                />
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default ChatWindow;
